$private->put('initiative:private-scene',['active'=>true,'order'=>['private-source','private-target'],'currentIndex'=>0,'turnSerial'=>0,'round'=>1,'combatId'=>'private-combat']);
$source=$private->payload('token:scene-one:token-player');$source=array_replace($source,['id'=>'private-source','layerId'=>'upper','x'=>40,'y'=>50]);
