$beam=['id'=>'hidden-beam','name'=>'Rayon fictif','revision'=>1,'status'=>'active','creatorCharacterId'=>'creator','sceneId'=>'private-scene','layerId'=>'upper','x'=>73,'y'=>22,'mark'=>['x'=>90,'y'=>22],'mana'=>88,'waitingForConsent'=>true,'definition'=>dsDefinition(['kind'=>'beam']),'participants'=>[['characterId'=>'creator','status'=>'approved','mana'=>88],['characterId'=>'guest','status'=>'pending']]];
