requireDevice(deviceCommand($beamDb,'device.place',['deviceId'=>$bid,'sourceTokenId'=>$token['id'],'expectedRevision'=>$beam['revision'],'x'=>$token['x'],'y'=>$token['y'],'mark'=>['x'=>90,'y'=>50]])->status===200,'Native recovered beam is placed with a new aim');
requireDevice($beamDb->payload('character:character-player')===$beforeSheet,'Beam recovery and redeployment do not pay installation or contribution again');
